// The equivalence tests of the definitions slice (A-9 S4): testdata/definitions.json is generated by driving the Python loader
// (tools/gen_gateway_definitions.py): a corpus of pinned files through agent_xrs._decide and definitions.from_pin (the YAML reader,
// the JSON schema, the pin rules), and scenarios of AgentXRs.poll over a real Python Gateway whose core takes PUT /v1/definitions from
// a recording server. Each case or step here must come out as Python's did, request for request. A case or step with "go" is a place
// Go deliberately differs: the expectation is Go's, and "why" says why. A "go" without a "why" fails, and so does a "why" without a
// "go".

type pyOutcome struct {
	Loaded         *pyLoaded `json:"loaded"`
	Rejected       *string   `json:"rejected"`
	RejectedPrefix string    `json:"rejected_prefix"`
	PublishError   string    `json:"python_publish_error"`
}

type pyLoaded struct {
	Doc    map[string]any `json:"doc"`
	Name   string         `json:"name"`
	RunsIn string         `json:"runs_in"`
	Scope  any            `json:"scope"`
	Agent  any            `json:"agent"`
}

type pyCase struct {
	Name     string     `json:"name"`
	Group    string     `json:"group"`
	Text     string     `json:"text"`
	XR       string     `json:"xr"`
	Owner    string     `json:"owner"`
	Reserved []string   `json:"reserved"`
	Python   pyOutcome  `json:"python"`
	Go       *pyOutcome `json:"go"`
	Why      string     `json:"why"`
}

type pyRequest struct {
	Method        string         `json:"method"`
	Path          string         `json:"path"`
	Body          map[string]any `json:"body"`
	Authorization string         `json:"authorization"`
}

type pyChanges struct {
	Added    []string         `json:"added"`
	Changed  []string         `json:"changed"`
	Removed  []string         `json:"removed"`
	Rejected []map[string]any `json:"rejected"`
	Cleared  []map[string]any `json:"cleared"`
}

type pyState struct {
	Loaded   []map[string]any `json:"loaded"`
	Rejected []map[string]any `json:"rejected"`
	Rows     []map[string]any `json:"rows"`
}

type pyStepExpect struct {
	Changes  pyChanges   `json:"changes"`
	State    pyState     `json:"state"`
	Fetched  []string    `json:"fetched"`
	Requests []pyRequest `json:"requests"`
}

type pyStep struct {
	pyStepExpect
	Label    string                    `json:"label"`
	At       string                    `json:"at"`
	Restart  bool                      `json:"restart"`
	XRs      []map[string]any          `json:"xrs"`
	Files    map[string]map[string]any `json:"files"`
	ListFail string                    `json:"list_fail"`
	Core     [][]any                   `json:"core"`
	Go       *pyStepExpect             `json:"go"`
	Why      string                    `json:"why"`
}

type pyScenario struct {
	Name           string         `json:"name"`
	Bundled        map[string]any `json:"bundled"`
	BundledVersion string         `json:"bundled_version"`
	Steps          []pyStep       `json:"steps"`
}

type defsFile struct {
	Bundled []string     `json:"bundled"`
	Cases   []pyCase     `json:"cases"`
	Scen    []pyScenario `json:"scenarios"`
}

func loadFile(t *testing.T) *defsFile {
	t.Helper()
	raw, err := os.ReadFile("testdata/definitions.json")
	if err != nil {
		t.Fatal(err)
	}
	var f defsFile
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	return &f
}

// stubReserved are the bundled definitions' names a pin may not take (their content does not matter to a pin's decision).
func stubReserved(names []string) map[string]*definitions.Definition {
	m := map[string]*definitions.Definition{}
	for _, n := range names {
		m[n] = &definitions.Definition{Name: n}
	}
	return m
}

// testPolicy is the policy `serve` builds, for the corpus's world: owner acme, the one runtime image the corpus uses, the default tools,
// pins bound to their app by namespace, and Python's reasons (the corpus compares them; production publishes redacted ones).
func testPolicy() definitions.PinPolicy {
	return definitions.PinPolicy{Tools: tools.Default(), AllowTools: definitions.DefaultPinTools(tools.Default()), Owners: []string{"acme"},
		ImageGlobs: []string{"ghcr.io/acme/runtime@sha256:*"}, BindApp: true, Detailed: true, Names: fixtureNames()}
}

var (
	namesOnce sync.Once
	names     map[string]string
)

// fixtureNames is the agent names the fixtures use, each listed for the corpus's namespace (AGENT_XRS_NAMES): the fixtures were written
// before a pinned agent's name belonged to its app. A case whose XR is named zz-... is left out, and is refused for its name.
func fixtureNames() map[string]string {
	namesOnce.Do(func() {
		raw, err := os.ReadFile("testdata/definitions.json")
		if err != nil {
			panic(err)
		}
		var f defsFile
		if err := json.Unmarshal(raw, &f); err != nil {
			panic(err)
		}
		names = map[string]string{}
		for _, c := range f.Cases {
			if !strings.HasPrefix(c.XR, "zz-") {
				names[c.XR] = "app-gate-api-cicd"
			}
		}
		for _, sc := range f.Scen {
			for _, st := range sc.Steps {
				for _, x := range st.XRs {
					md, _ := x["metadata"].(map[string]any)
					n, _ := md["name"].(string)
					ns, _ := md["namespace"].(string)
					names[n] = ns
				}
			}
		}
	})
	return names
}

func decideGo(t *testing.T, c pyCase) pyOutcome {
	t.Helper()
	path := "agents/" + c.XR + ".yaml"
	doc, reason, _ := definitions.ReadPinnedFile(path, c.Text, true)
	if reason != "" {
		return pyOutcome{Rejected: &reason}
	}
	src := definitions.Source{Kind: "cluster", Repo: definitions.S("acme/gate-api"), Path: definitions.S(path), Commit: definitions.S("1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d7e8f9a0b"),
		Namespace: definitions.S("app-gate-api-cicd"), XR: definitions.S(c.XR)}
	l, rej := definitions.FromPin(doc, src, c.Owner, stubReserved(c.Reserved), tools.Default(), testPolicy())
	if rej != nil {
		return pyOutcome{Rejected: &rej.Reason}
	}
	return pyOutcome{Loaded: &pyLoaded{Doc: l.Doc, Name: l.Def.Name, RunsIn: l.Def.RunsIn(), Scope: l.Def.Scope(), Agent: l.Def.AgentDef()}}
}

// matches reports whether got is what want expects: a loaded pin with the same document, name, scope and agent, or a rejection with
// the same reason (or one that starts with RejectedPrefix).
func matches(t *testing.T, got, want pyOutcome) string {
	t.Helper()
	switch {
	case want.Loaded != nil:
		if got.Loaded == nil {
			return fmt.Sprintf("rejected %q, want it loaded", *got.Rejected)
		}
		for what, pair := range map[string][2]any{"doc": {got.Loaded.Doc, want.Loaded.Doc}, "scope": {got.Loaded.Scope, want.Loaded.Scope}, "agent": {got.Loaded.Agent, want.Loaded.Agent}} {
			if !reflect.DeepEqual(norm(t, pair[0]), norm(t, pair[1])) {
				return fmt.Sprintf("%s\n got %v\nwant %v", what, norm(t, pair[0]), norm(t, pair[1]))
			}
		}
		if got.Loaded.Name != want.Loaded.Name || got.Loaded.RunsIn != want.Loaded.RunsIn {
			return "name or runs_in differ"
		}
	case want.RejectedPrefix != "":
		if got.Rejected == nil || !strings.HasPrefix(*got.Rejected, want.RejectedPrefix) {
			return fmt.Sprintf("got %v, want a rejection starting %q", got, want.RejectedPrefix)
		}
	case want.Rejected != nil:
		if got.Rejected == nil {
			return fmt.Sprintf("loaded, want rejected %q", *want.Rejected)
		}
		if *got.Rejected != *want.Rejected {
			return fmt.Sprintf("reason\n got %q\nwant %q", *got.Rejected, *want.Rejected)
		}
	}
	return ""
}

func TestPinnedFilesDecideAsPythonDecidesThem(t *testing.T) {
	f := loadFile(t)
	if len(f.Cases) < 250 {
		t.Fatalf("only %d cases: the corpus must stay broad", len(f.Cases))
	}
	loaded, rejected, deviations := 0, 0, 0
	for _, c := range f.Cases {
		want := c.Python
		if p := goWhyProblem(c.Go != nil, c.Why); p != "" {
			t.Errorf("%s: %s", c.Name, p)
			continue
		}
		if c.Go != nil {
			want = *c.Go
			deviations++
			if reflect.DeepEqual(norm(t, *c.Go), norm(t, c.Python)) {
				t.Errorf("%s: the `go` expectation is the Python one: drop it", c.Name)
			}
		}
		got := decideGo(t, c)
		if msg := matches(t, got, want); msg != "" {
			t.Errorf("%s: %s", c.Name, msg)
		}
		if got.Loaded != nil {
			loaded++
		} else {
			rejected++
		}
	}
	if loaded < 50 || rejected < 150 {
		t.Fatalf("the corpus does not exercise both outcomes: %d loaded, %d rejected", loaded, rejected)
	}
	t.Logf("%d cases: %d loaded, %d rejected, %d deliberate differences (each with a why)", len(f.Cases), loaded, rejected, deviations)
}

func TestEveryGroupOfTheCorpusIsThere(t *testing.T) {
	f := loadFile(t)
	groups := map[string]int{}
	for _, c := range f.Cases {
		groups[c.Group]++
	}
	for _, g := range []string{"valid", "schema", "name", "description", "owner", "identity", "tier", "limits", "repos", "apis", "apps", "image", "enum", "sidecars",
		"instructions", "triggers", "pin", "yaml", "yaml-strict", "tools", "airframe"} {
		if groups[g] == 0 {
			t.Errorf("no case of the group %q", g)
		}
	}
}

// -- the poller's scenarios -----------------------------------------------------------------------------------------------------

type fakeLister struct {
	mu    sync.Mutex
	items []map[string]any
	fixed map[string][]map[string]any // when set, what each namespace answers, whatever its items say
	fail  string
	calls int
	ns    []string
}

func (l *fakeLister) listed() []string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return append([]string(nil), l.ns...)
}

func (l *fakeLister) ListAgents(_ context.Context, ns string) ([]map[string]any, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.calls++
	l.ns = append(l.ns, ns)
	if l.fixed != nil && l.fail == "" {
		return l.fixed[ns], nil
	}
	switch l.fail {
	case "airframe":
		return nil, errors.New("API server unreachable: URLError")
	case "denied":
		return nil, &core.Denied{Rule: "AF-K8S-403", Message: "the API server refused Clearance's identity (403)"}
	}
	var out []map[string]any
	for _, it := range l.items {
		if md, _ := it["metadata"].(map[string]any); md["namespace"] == ns {
			out = append(out, it)
		}
	}
	return out, nil
}

type fakeFiles struct {
	mu    sync.Mutex
	files map[string]map[string]any
	calls []string
}

func (f *fakeFiles) ReadFile(_ context.Context, repo, path, ref string) (map[string]any, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	key := repo + "|" + path + "|" + ref
	f.calls = append(f.calls, key)
	v := f.files[key]
	switch {
	case v == nil || v["missing"] != nil:
		return map[string]any{"path": path, "ref": ref, "found": false}, nil
	case v["denied"] != nil:
		d := v["denied"].([]any)
		return nil, &core.Denied{Rule: d[0].(string), Message: d[1].(string)}
	case v["transient"] != nil:
		return nil, errors.New("GitHub unreachable: URLError")
	case v["dir"] != nil:
		return map[string]any{"path": path, "ref": ref, "type": "dir", "entries": []any{}}, nil
	case v["binary"] != nil:
		return map[string]any{"path": path, "ref": ref, "type": "file", "size": 5, "content": nil, "note": "binary"}, nil
	case v["text"] != nil:
		return map[string]any{"path": path, "ref": ref, "type": "file", "content": v["text"]}, nil
	}
	// a document: written as YAML the way Python's yaml.safe_dump does for these (block style)
	b, err := yamlOf(v["doc"])
	if err != nil {
		return nil, err
	}
	return map[string]any{"path": path, "ref": ref, "type": "file", "content": b}, nil
}

// memStore is the gateway database's definitions table.
type memStore struct {
	mu   sync.Mutex
	rows []definitions.Row
}

func (m *memStore) ReplaceDefinitions(_ context.Context, rows []definitions.Row) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.rows = rows
	return nil
}

// recordingCore is the core's PUT /v1/definitions: one answer per request from a queue, else a 200 that counts what it was sent.
type recordingCore struct {
	mu       sync.Mutex
	requests []pyRequest
	answers  [][]any
	srv      *httptest.Server
}

func newRecordingCore(t *testing.T) *recordingCore {
	rc := &recordingCore{}
	rc.srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		var body map[string]any
		_ = json.Unmarshal(raw, &body)
		rc.mu.Lock()
		rc.requests = append(rc.requests, pyRequest{Method: r.Method, Path: r.URL.Path, Body: body, Authorization: r.Header.Get("Authorization")})
		status, ans := 200, any(nil)
		if len(rc.answers) > 0 {
			status, ans = int(rc.answers[0][0].(float64)), rc.answers[0][1]
			rc.answers = rc.answers[1:]
		}
		rc.mu.Unlock()
		if ans == nil {
			pins, _ := body["pins"].([]any)
			bundled, _ := body["bundled"].([]any)
			ans = map[string]any{"added": []any{}, "changed": []any{}, "removed": []any{}, "rejected": []any{}, "cleared": []any{}, "cluster": len(pins), "provided": len(bundled)}
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_ = json.NewEncoder(w).Encode(ans)
	}))
	t.Cleanup(rc.srv.Close)
	return rc
}

func (rc *recordingCore) take() []pyRequest {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	out := rc.requests
	rc.requests = nil
	return out
}

func yamlOf(v any) (string, error) { b, err := json.Marshal(v); return string(b), err }

func bundledSet(t *testing.T, docs map[string]any) map[string]*definitions.Definition {
	t.Helper()
	out := map[string]*definitions.Definition{}
	for n, d := range docs {
		def, err := definitions.ParseDoc(definitions.FromPlain(d).(*definitions.OMap), tools.Default())
		if err != nil {
			t.Fatalf("bundled %s: %v", n, err)
		}
		out[n] = def
	}
	return out
}

func stepState(set *definitions.Set, store *memStore) pyState {
	loaded, rejected, _ := set.ClusterSet()
	st := pyState{Loaded: []map[string]any{}, Rejected: []map[string]any{}, Rows: []map[string]any{}}
	for _, l := range loaded {
		st.Loaded = append(st.Loaded, map[string]any{"name": l.Name(), "source": l.Source.View()})
	}
	for _, r := range rejected {
		st.Rejected = append(st.Rejected, rejectedView(r))
	}
	store.mu.Lock()
	defer store.mu.Unlock()
	for _, r := range store.rows {
		st.Rows = append(st.Rows, r)
	}
	return st
}

func rejectedView(r definitions.Rejected) map[string]any {
	return map[string]any{"name": r.Name, "source": r.Source.View(), "reason": r.Reason}
}

func changesOf(c definitions.Changes) pyChanges {
	out := pyChanges{Added: []string{}, Changed: []string{}, Removed: []string{}, Rejected: []map[string]any{}, Cleared: []map[string]any{}}
	out.Added, out.Changed, out.Removed = append(out.Added, c.Added...), append(out.Changed, c.Changed...), append(out.Removed, c.Removed...)
	for _, r := range c.Rejected {
		out.Rejected = append(out.Rejected, rejectedView(r))
	}
	for _, r := range c.Cleared {
		out.Cleared = append(out.Cleared, rejectedView(r))
	}
	return out
}

func TestThePollerEqualsPythonStepByStep(t *testing.T) {
	f := loadFile(t)
	if len(f.Scen) < 8 {
		t.Fatalf("only %d scenarios", len(f.Scen))
	}
	steps, deviations, requests := 0, 0, 0
	for _, sc := range f.Scen {
		t.Run(sc.Name, func(t *testing.T) {
			rc := newRecordingCore(t)
			cl, err := client.New(core.ClientOptions(rc.srv.URL, client.StaticToken("fixture-core-token"), 5*time.Second))
			if err != nil {
				t.Fatal(err)
			}
			store := &memStore{}
			var lister = &fakeLister{}
			var files = &fakeFiles{}
			var now time.Time
			build := func() (*definitions.Set, *definitions.Poller) {
				set := definitions.NewSet(bundledSet(t, sc.Bundled))
				c := core.New(cl, nil, false)
				c.Log = slog.New(slog.NewTextHandler(io.Discard, nil))
				c.SetDefinitionsClient(nil, sc.BundledVersion)
				var snapshot map[string]*definitions.Definition
				mgr := definitions.NewManager(set, store, c, func(m map[string]*definitions.Definition) { snapshot = m }, slog.New(slog.NewTextHandler(io.Discard, nil)))
				_ = snapshot
				p := definitions.NewPoller()
				p.Namespaces = []string{"app-gate-api-cicd", "app-other-cicd"}
				p.Lister, p.Files, p.Sink, p.Set, p.Baseline = lister, files, mgr, set, tools.Default()
				p.Policy = testPolicy()
				p.Now = func() time.Time { return now }
				p.Log = slog.New(slog.NewTextHandler(io.Discard, nil))
				return set, p
			}
			set, p := build()
			for i, st := range sc.Steps {
				if st.Restart {
					prev := store.rows
					set, p = build()
					store.rows = prev
					p.Seed(prev)
				}
				now, _ = time.Parse(time.RFC3339, st.At)
				lister.items, lister.fail = st.XRs, st.ListFail
				files.files, files.calls = st.Files, nil
				rc.answers = st.Core
				rc.take()
				ch := p.Poll(context.Background())
				got := pyStepExpect{Changes: changesOf(ch), State: stepState(set, store), Fetched: append([]string{}, files.calls...), Requests: rc.take()}
				if got.Requests == nil {
					got.Requests = []pyRequest{}
				}
				want := st.pyStepExpect
				if p := goWhyProblem(st.Go != nil, st.Why); p != "" {
					t.Errorf("step %d (%s): %s", i, st.Label, p)
					continue
				}
				if st.Go != nil {
					want = *st.Go
					deviations++
					if reflect.DeepEqual(norm(t, *st.Go), norm(t, st.pyStepExpect)) {
						t.Errorf("step %d (%s): the `go` expectation is the Python one: drop it", i, st.Label)
					}
				}
				compareStep(t, i, st.Label, got, want)
				steps++
				requests += len(got.Requests)
			}
		})
	}
	t.Logf("%d scenarios, %d steps, %d publish requests compared, %d steps with a deliberate difference", len(f.Scen), steps, requests, deviations)
}

// firstDiff names the first place two decoded JSON values differ ("" when they do not).
func firstDiff(a, b any, path string) string {
	switch x := a.(type) {
	case map[string]any:
		y, ok := b.(map[string]any)
		if !ok {
			return fmt.Sprintf("%s: %v vs %v", path, a, b)
		}
		keys := map[string]bool{}
		for k := range x {
			keys[k] = true
		}
		for k := range y {
			keys[k] = true
		}
		for k := range keys {
			if d := firstDiff(x[k], y[k], path+"/"+k); d != "" {
				return d
			}
		}
		return ""
	case []any:
		y, ok := b.([]any)
		if !ok || len(x) != len(y) {
			return fmt.Sprintf("%s: %d elements vs %v", path, len(x), b)
		}
		for i := range x {
			if d := firstDiff(x[i], y[i], fmt.Sprintf("%s/%d", path, i)); d != "" {
				return d
			}
		}
		return ""
	}
	if !reflect.DeepEqual(a, b) {
		return fmt.Sprintf("%s: %v vs %v", path, a, b)
	}
	return ""
}

// stepProblems is every way got is not want: the changes, the resulting set and rows, the files fetched, and the requests the core was
// sent (an extra, a missing or a reordered request is a problem, as is a different body).
func stepProblems(t *testing.T, got, want pyStepExpect) []string {
	t.Helper()
	var out []string
	if d := firstDiff(norm(t, got.Changes), norm(t, want.Changes), ""); d != "" {
		out = append(out, "changes differ at "+d)
	}
	if d := firstDiff(norm(t, got.State), norm(t, want.State), ""); d != "" {
		out = append(out, "state differs at "+d)
	}
	if !reflect.DeepEqual(got.Fetched, append([]string{}, want.Fetched...)) {
		out = append(out, fmt.Sprintf("fetched %v, want %v", got.Fetched, want.Fetched))
	}
	if len(got.Requests) != len(want.Requests) {
		return append(out, fmt.Sprintf("%d requests, want %d (extra or missing)", len(got.Requests), len(want.Requests)))
	}
	for j := range want.Requests {
		if d := firstDiff(norm(t, got.Requests[j]), norm(t, want.Requests[j]), ""); d != "" {
			out = append(out, fmt.Sprintf("request %d (extra, missing or reordered) differs at %s", j, d))
		}
	}
	return out
}

func compareStep(t *testing.T, i int, label string, got, want pyStepExpect) {
	t.Helper()
	for _, p := range stepProblems(t, got, want) {
		t.Errorf("step %d (%s): %s", i, label, p)
	}
}

// goWhyProblem is what a case or step with a `go` and no `why`, or a `why` and no `go`, is.
func goWhyProblem(hasGo bool, why string) string {
	if hasGo != (why != "") {
		return "a `go` needs a `why` and a `why` needs a `go`"
	}
	return ""
}

// The harness fails where the task says it must: a `go` without a `why`, and an extra, a missing or a reordered request.
func TestTheHarnessCanFail(t *testing.T) {
	req := func(n int) pyRequest {
		return pyRequest{Method: "PUT", Path: "/v1/definitions", Body: map[string]any{"n": float64(n)}, Authorization: "Bearer x"}
	}
	want := pyStepExpect{Fetched: []string{"a|b|c"}, Requests: []pyRequest{req(1), req(2)}}
	same := want
	if p := stepProblems(t, same, want); len(p) != 0 {
		t.Fatalf("identical expectations must pass: %v", p)
	}
	variants := map[string]pyStepExpect{
		"an extra request":     {Fetched: want.Fetched, Requests: []pyRequest{req(1), req(2), req(3)}},
		"a missing request":    {Fetched: want.Fetched, Requests: []pyRequest{req(1)}},
		"a reordered request":  {Fetched: want.Fetched, Requests: []pyRequest{req(2), req(1)}},
		"a changed body":       {Fetched: want.Fetched, Requests: []pyRequest{req(1), req(9)}},
		"a changed header":     {Fetched: want.Fetched, Requests: []pyRequest{req(1), {Method: "PUT", Path: "/v1/definitions", Body: req(2).Body, Authorization: "Bearer y"}}},
		"a file fetched twice": {Fetched: []string{"a|b|c", "a|b|c"}, Requests: want.Requests},
		"changes that differ":  {Changes: pyChanges{Added: []string{"x"}}, Fetched: want.Fetched, Requests: want.Requests},
		"a different state":    {State: pyState{Loaded: []map[string]any{{"name": "x"}}}, Fetched: want.Fetched, Requests: want.Requests},
	}
	for name, got := range variants {
		if len(stepProblems(t, got, want)) == 0 {
			t.Errorf("%s was not noticed", name)
		}
	}
	if goWhyProblem(true, "") == "" || goWhyProblem(false, "because") == "" || goWhyProblem(true, "because") != "" || goWhyProblem(false, "") != "" {
		t.Error("a `go` without a `why`, and a `why` without a `go`, must fail")
	}
	// a case whose Go outcome differs from Python's is noticed, and one that matches is not
	loaded := pyOutcome{Loaded: &pyLoaded{Name: "a", Doc: map[string]any{"name": "a"}}}
	rej := func(s string) pyOutcome { return pyOutcome{Rejected: &s} }
	for _, c := range []struct{ got, want pyOutcome }{{rej("x"), loaded}, {loaded, rej("x")}, {rej("x"), rej("y")}, {rej("abc"), pyOutcome{RejectedPrefix: "abd"}}} {
		if matches(t, c.got, c.want) == "" {
			t.Errorf("%v vs %v: a difference was not noticed", c.got, c.want)
		}
	}
	if matches(t, rej("abc"), pyOutcome{RejectedPrefix: "ab"}) != "" || matches(t, loaded, loaded) != "" || matches(t, rej("x"), rej("x")) != "" {
		t.Error("equal outcomes must match")
	}
}

func TestTheSchemaCopyIsTheOneThePythonLoaderValidatesWith(t *testing.T) {
	// The copy is generated; this holds it to the file Python reads when the checkout has both (the repo does).
	py, err := os.ReadFile("../../../src/autopilot/engine/schemas/agent-definition.schema.json")
	if err != nil {
		t.Skip("no Python source beside the Go module")
	}
	here, err := os.ReadFile("agent-definition.schema.json")
	if err != nil {
		t.Fatal(err)
	}
	if string(py) != string(here) {
		t.Fatal("agent-definition.schema.json is not the Python schema: run python tools/gen_gateway_registry.py")
	}
}
